from rdkit import Chem
from rdkit.Chem import AllChem
import numpy as np
np.set_printoptions(precision=3,suppress=True)
coords=[]; atoms=[]; edges=[]
def atom(el,xyz,arom=False,charge=0):
 a=Chem.Atom(el); a.SetIsAromatic(arom); a.SetFormalCharge(charge); atoms.append(a);coords.append(np.array(xyz,float));return len(atoms)-1
def bond(a,b,typ=Chem.BondType.SINGLE):edges.append((a,b,typ))
def unit(v):return v/np.linalg.norm(v)
def remaining(u,v):
 u=unit(u);v=unit(v);w=np.linalg.lstsq(np.stack([u,v]),np.array([-1/3,-1/3]),rcond=None)[0];n=unit(np.cross(u,v));return w+np.sqrt(1-w@w)*n,w-np.sqrt(1-w@w)*n
def tripod(u,phase):
 u=unit(u); ref=np.array([0.,0.,1.])
 if abs(u@ref)>.95:ref=np.array([0.,1.,0.])
 a=unit(np.cross(u,ref));b=np.cross(u,a)
 return [-u/3+np.sqrt(8/9)*(np.cos(phase+t*2*np.pi/3)*a+np.sin(phase+t*2*np.pi/3)*b) for t in range(3)]
R=1.205; z=2.14
for i in range(5):
 ang=np.pi/2+i*2*np.pi/5
 atom('C',[R*np.cos(ang),R*np.sin(ang),z],arom=True,charge=(-1 if i==0 else 0))
for i in range(5):bond(i,(i+1)%5,Chem.BondType.AROMATIC)
fixed=list(range(5))
for r in [1,4]:
 radial=unit(coords[r]*[1,1,0]); si=atom('Si',coords[r]+radial*1.86);bond(r,si)
 bridge_dir=radial/3+np.array([0,0,-np.sqrt(8/9)])
 bridge=atom('C',coords[si]+1.88*bridge_dir);bond(si,bridge)
 # P close to metal and downward from CH2
 p=atom('P',[np.sign(radial[0])*2.5,0,-.55]);bond(bridge,p)
 fixed.extend([si,bridge,p])
 for direction in remaining(coords[r]-coords[si],coords[bridge]-coords[si]):
  a=atom('C',coords[si]+1.88*direction);bond(si,a)
 for j,direction in enumerate(remaining(coords[bridge]-coords[p],-coords[p])):
  c=atom('C',coords[p]+1.86*direction);bond(p,c)
  for d in tripod(coords[p]-coords[c],.5+j*1.2)[:2]:
   a=atom('C',coords[c]+1.53*d);bond(c,a)
m=Chem.RWMol()
for a in atoms:m.AddAtom(a)
for a,b,t in edges:m.AddBond(a,b,t)
m=m.GetMol();Chem.SanitizeMol(m)
conf=Chem.Conformer(m.GetNumAtoms())
for i,c in enumerate(coords):conf.SetAtomPosition(i,c)
m.AddConformer(conf)
m=Chem.AddHs(m,addCoords=True)
print('ligand',Chem.MolToSmiles(m),m.GetNumAtoms(), 'fixed',fixed)
ff=AllChem.UFFGetMoleculeForceField(m)
for i in fixed:ff.AddFixedPoint(i)
ff.Initialize();print('UFF init',ff.CalcEnergy()); ff.Minimize(maxIts=3000);print('UFF final',ff.CalcEnergy())
Chem.MolToMolFile(m,'ligand.mol')
xyz=m.GetConformer().GetPositions();els=[a.GetSymbol() for a in m.GetAtoms()]
# zirconium, chloride, methyl
metal=np.array([0.,0.,0.]); cl=np.array([0,2.18,-.95]); me=np.array([0,-1.96,-.95])
xyz=list(xyz)+[metal,cl,me];els+=['Zr','Cl','C']
for d in tripod(metal-me,.2):xyz.append(me+d*1.095);els.append('H')
with open('initial.xyz','w') as f:
 f.write(f'{len(els)}\nCp-bis(silylmethylene-diisopropylphosphine) Zr methyl chloride; doublet\n')
 for e,p in zip(els,xyz):f.write(f'{e} {p[0]: .8f} {p[1]: .8f} {p[2]: .8f}\n')
